-- Вспомогательная функция для создания кнопок
local function createButton(name, text, position, callback)
    local btn = Instance.new("TextButton", G2L["scroll"]);
    btn.BorderSizePixel = 2;
    btn.TextSize = 14;
    btn.TextColor3 = Color3.fromRGB(255, 255, 255);
    btn.BackgroundColor3 = Color3.fromRGB(0, 0, 0);
    btn.FontFace = Font.new([[rbxasset://fonts/families/SourceSansPro.json]], Enum.FontWeight.Regular, Enum.FontStyle.Normal);
    btn.Size = UDim2.new(0, 120, 0, 35);
    btn.BorderColor3 = Color3.fromRGB(0, 255, 0);
    btn.Text = text;
    btn.Position = position;
    btn.Name = name;
    btn.MouseButton1Click:Connect(callback);
end

-- Функция для отправки команд через HDAdmin
local function sendCommand(cmd)
    local ReplicatedStorage = game:GetService("ReplicatedStorage")
    local RequestCommand = ReplicatedStorage:WaitForChild("HDAdminHDClient").Signals.RequestCommandSilent
    RequestCommand:InvokeServer(cmd)
end

-- Функция для отправки музыки (2 команды)
local function playMusic(musicId, pitchValue)
    sendCommand(";music " .. musicId)
    wait(0.5)
    sendCommand(";pitch " .. pitchValue)
end

