-- Particles (Visual) - название изменено
createButton("Particles", "Particles (Visual)", UDim2.new(0.69, 0, 0.09, 0), function()
    local player = game.Players.LocalPlayer
    local char = player.Character
    if not char then return end
    local hrp = char:FindFirstChild("HumanoidRootPart")
    if not hrp then return end

    local part = Instance.new("Part")
    part.Size = Vector3.new(1, 1, 1)
    part.Anchored = true
    part.CanCollide = false
    part.Transparency = 1
    part.Position = hrp.Position + Vector3.new(0, 2, 0)
    part.Parent = workspace

    local particles = Instance.new("ParticleEmitter")
    particles.Texture = "rbxassetid://127243975327696"
    particles.Rate = 150
    particles.Lifetime = NumberRange.new(1.5, 3)
    particles.SpreadAngle = Vector2.new(360, 360)
    particles.Speed = NumberRange.new(3, 8)
    particles.Rotation = NumberRange.new(0, 360)
    particles.RotSpeed = NumberRange.new(-50, 50)
    particles.Size = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 1),
        NumberSequenceKeypoint.new(1, 0)
    })
    particles.Transparency = NumberSequence.new({
        NumberSequenceKeypoint.new(0, 0.2),
        NumberSequenceKeypoint.new(1, 1)
    })
    particles.Color = ColorSequence.new(Color3.fromRGB(255, 180, 80))
    particles.Enabled = true
    particles.Parent = part

    game:GetService("Debris"):AddItem(part, 7)
end)

